'use strict';
const groups={Onboarding:onboardingScreens,Auth:['Splash','Login','Login · error','Sign up','Verify OTP','Forgot password','Verify reset','Reset password'],Calendar:['Calendar','Calendar day'],Subscriptions:['Home','Home · loading','Home · empty','Home · quiet','Spending breakdown','This month','List','List · empty','List · upcoming','List · no renewal','List · active','List · trial','List · trial ended','List · due today','List · cancelled','List · expired','Add sheet','Add form','Detail','Detail · trial','Detail · trial ended','Detail · cancelled','Detail · no renewal','Platform subscriptions','Edit','AI chat','AI chat · trial','AI chat · attachment','Voice','Gmail · scanning','Gmail · review','Trial review','Gmail · nothing found','Gmail · interrupted','Delete confirm','Widgets'],Alerts:['Alerts','Alerts · trial','Alerts · empty','Alerts · notifications off','Reminder settings'],Profile:['Profile','Profile · incomplete','Profile · social','Connected inbox','Connected inbox · reconnect','Connected inbox · syncing','Connected inbox · error','Inbox subscriptions','Edit profile','Change password','History','History · empty','Payments','Payments · empty']};
const slug=s=>s.toLowerCase().replace(/ · /g,'-').replace(/\s+/g,'-');
const screens=Object.values(groups).flat();
let current='Home',previous='Home',demoName='Netflix',demoPrice='15.99';
const state={reminder:true,cycle:'Monthly',created:false};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const platformLogo=name=>{const key=({'Netflix':'netflix','Spotify':'spotify','iCloud+':'icloud','Gmail':'gmail','Figma':'figma','Notion':'notion','Duolingo':'duolingo'})[name];return key?`<img class="platform-logo" src="assets/platforms/${key}.svg" alt="${escape(name)} logo">`:`<span aria-hidden="true">${escape(name[0])}</span>`;};
function backButton({to,attributes='',label='Go back',className=''}={}){return `<button type="button" class="back header-back ${escape(className)}" ${to!==undefined?`data-go="${escape(to)}"`:''} ${attributes} aria-label="${escape(label)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m15 6-6 6 6 6"/></svg></button>`;}
const btn=(label,to,cls='primary')=>{if(cls==='back'||cls==='ob-back')return backButton({to,className:cls==='ob-back'?'ob-back':''});const glyph=cls==='plus'?'M12 5v14M5 12h14':null;return `<button class="${cls}" data-go="${escape(to)}" ${glyph?`aria-label="${cls==='plus'?'Add subscription':'Go back'}"`:''}>${glyph?`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${glyph}"/></svg>`:label}</button>`;};
const action=(label,name,cls='secondary')=>`<button class="${cls}" data-action="${name}">${label}</button>`;
const input=(label,value='',type='text',name='')=>`<label>${label}<input type="${type}" name="${name||slug(label)}" value="${escape(value)}" ${label.includes('optional')?'':'required'} ${type==='password'?'minlength="6"':type==='number'?'step="0.01" min="0"':''}></label>`;
const fr=(a,b)=>`<div class="fieldrow"><span>${a}</span><span>${b}</span></div>`;
const panel=x=>`<div class="panel">${x}</div>`;
const heading=(title,back=false,plus=false)=>`<div class="head">${back?btn('‹','back','back'):''}<h2>${title}</h2>${plus?btn('+','Add sheet','plus'):''}</div>`;
const brand=()=>`<div class="brand"><img src="assets/renewless-mark.svg" alt="Renewless R"><span>Renewless</span></div><p class="tagline">Stop the subscription renewals you don’t need.</p>`;
const socialIcon=provider=>provider==='Google'?`<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.6 12.23c0-.71-.06-1.39-.18-2.05H12v3.88h5.38a4.6 4.6 0 0 1-2 3.02v2.51h3.24c1.9-1.75 2.98-4.33 2.98-7.36Z"/><path fill="#34A853" d="M12 22c2.7 0 4.96-.9 6.62-2.41l-3.24-2.51c-.9.6-2.05.96-3.38.96-2.6 0-4.8-1.76-5.59-4.12H3.07v2.59A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.41 13.92A6 6 0 0 1 6.1 12c0-.67.11-1.32.31-1.92V7.49H3.07A10 10 0 0 0 2 12c0 1.61.38 3.14 1.07 4.51l3.34-2.59Z"/><path fill="#EA4335" d="M12 5.96c1.47 0 2.79.51 3.83 1.51l2.87-2.87A9.6 9.6 0 0 0 12 2a10 10 0 0 0-8.93 5.49l3.34 2.59C7.2 7.72 9.4 5.96 12 5.96Z"/></svg>`:`<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M17.05 12.54c.03 3.16 2.77 4.21 2.8 4.22-.02.08-.44 1.5-1.45 2.97-.87 1.27-1.78 2.54-3.2 2.57-1.39.03-1.84-.83-3.44-.83-1.59 0-2.09.8-3.41.86-1.37.05-2.41-1.38-3.29-2.64C3.27 17.11 1.9 12.4 3.74 9.22a5.1 5.1 0 0 1 4.31-2.61c1.35-.03 2.62.91 3.44.91.82 0 2.36-1.13 3.98-.96.68.03 2.6.27 3.83 2.07-.1.06-2.28 1.33-2.25 3.91ZM14.43 4.84c.73-.88 1.22-2.1 1.09-3.32-1.05.04-2.32.7-3.07 1.58-.67.78-1.26 2.03-1.1 3.22 1.17.09 2.36-.59 3.08-1.48Z"/></svg>`;
const socialButton=provider=>`<button class="secondary social-button" data-go="Home">${socialIcon(provider)}<span>Continue with ${provider}</span></button>`;
const loop=()=>`<button data-action="loop" aria-label="React with Loop"><img class="loop" src="assets/loop-mascot.svg" alt="Loop companion"></button>`;
const empty=(title,copy,cta=false,mascot=true)=>`<div class="empty">${mascot?loop():''}<h3>${title}</h3><p>${copy}</p>${cta?btn('Add manually','Add form')+btn('Connect Gmail','Gmail · scanning','secondary'):''}</div>`;
const icons={Home:'<path d="m3 10 9-7 9 7v10H3z M9 20v-7h6v7"/>',List:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',Calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 10h18M7 14h2M12 14h2M7 18h2"/>',Alerts:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4"/>',Profile:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>'};
const tabs=()=>`<nav class="tabs" aria-label="App navigation">${Object.keys(icons).map(t=>`<button class="${current.startsWith(t)?'selected':''}" data-go="${t}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[t]}</svg>${t}</button>`).join('')}</nav>`;
function subscriptionStatus(record){const r=trackedRecord(record);if(r.status==='Expired')return {key:'expired',label:'Expired'};if(r.status==='Cancelled')return {key:'cancelled',label:'Cancelled'};if(r.trialEnded)return {key:'trial-ended',label:'Trial ended'};if(r.trial){const days=Math.round((Date.parse(r.trialEnd)-Date.parse(calendarToday))/86400000);return {key:'trial',label:days===0?'Trial ends today':days<=7?'Trial ending soon':'On trial'};}if(!r.renewal)return {key:'needs-date',label:'Needs date'};const days=Math.round((Date.parse(r.renewal)-Date.parse(calendarToday))/86400000);return days===0?{key:'due-today',label:'Due today'}:days>0&&days<=7?{key:'renewing-soon',label:'Renewing soon'}:{key:'active',label:'Active'};}
const rows=(kind='normal')=>`<div class="rows">${(kind==='history'?[['Disney+','13.99','Expired'],['Adobe','59.99','Cancelled'],['NYT','17.00','Expired']]:kind==='none'?[['Notion','10.00','No renewal'],['Figma','15.00','No renewal']]:[[demoName,demoPrice,'27 Oct · Estimated'],['Spotify','11.99','29 Oct'],['iCloud+','2.99','30 Oct']]).map(([name,price,date])=>`<button class="row" data-go="${kind==='none'?'Detail · no renewal':kind==='history'?'Detail · cancelled':'Detail'}" data-name="${escape(name)}" data-price="${price}"><span class="avatar">${platformLogo(name)}</span><span class="body"><strong>${escape(name)}</strong><small class="${kind==='history'?'status-'+date.toLowerCase():kind==='none'?'status-needs-date':''}">${date}</small></span><span class="amount">$${price}<small>${kind==='history'?'History':kind==='none'?'Needs date':'Upcoming'}</small></span></button>`).join('')}</div>`;
const stats=()=>`<div class="stats">${[['Active',state.created?'13':'12'],['Renewing soon','3'],['This month','$86'],['Expired','2']].map(([a,b])=>panel(`<span class="metric-label">${a}</span><strong ${a==='Expired'?'class="danger"':''}>${b}</strong>`)).join('')}</div>`;
const chartData={paid:34.40,total:86,categories:[['Entertainment',34],['Productivity',26],['Education',17],['Other',9]],months:[['Oct',86],['Nov',92],['Dec',84],['Jan',110],['Feb',86],['Mar',95]]};
function spendingCharts(full=false){
 const percent=Math.round(chartData.paid/chartData.total*100);
 const gauge=`<section class="panel chart-card"><p class="eyebrow">THIS MONTH · USD</p><div class="gauge" role="img" aria-label="${percent}% of estimated monthly charges paid: $34.40 of $86"><svg viewBox="0 0 200 120" aria-hidden="true"><path class="track" d="M20 100 A80 80 0 0 1 180 100" pathLength="100"/><path class="meter" d="M20 100 A80 80 0 0 1 180 100" pathLength="100" stroke-dasharray="${percent} 100"/></svg><div class="gauge-value">${percent}<small>%</small></div></div><div class="chart-totals"><div><strong>$34.40</strong><small>Paid · estimated</small></div><div><strong>$51.60</strong><small>Still to come</small></div></div><p class="note">$86 estimated this month</p></section>`;
 const categories=`<section class="panel chart-card"><h3>Where it goes</h3><p class="note">$86 this month, by category · USD</p><div class="donut" role="img" aria-label="Category breakdown of $86: Entertainment $34, Productivity $26, Education $17, Other $9"><div><strong>$86</strong><small>This month</small></div></div><div class="category-chart">${chartData.categories.map(([label,value])=>`<div class="category-row"><span>${label}</span><div class="category-track" aria-hidden="true"><i style="width:${value/86*100}%"></i></div><small>${Math.round(value/86*100)}%</small><strong>$${value}</strong></div>`).join('')}</div></section>`;
 const bars=`<section class="panel chart-card"><h3>Coming up · 6 months</h3><p class="note">Estimated subscription charges · USD</p><div class="chart-totals"><div><strong>$553</strong><small>Total projected</small></div><div><strong>$110</strong><small>Highest · January</small></div></div><div class="bar-chart" aria-label="Monthly projected charges">${chartData.months.map(([month,value],i)=>`<button class="bar-column ${i===0?'selected':''}" data-month="${month}" data-value="${value}" aria-label="${month}: $${value} estimated" aria-pressed="${i===0}"><span class="bar-value">$${value}</span><span class="bar-space"><i style="height:${value/110*100}%"></i></span><small>${month}</small></button>`).join('')}</div><p class="chart-selection" aria-live="polite">October · $86 estimated</p></section>`;
 return (current.startsWith('Home')?homeMonthCard():gauge)+(full?(current.startsWith('Home')?topSpendingCard():categories)+(current.startsWith('Home')?homeForecast():bars):btn('See spending breakdown','Payments','secondary'));
}
function detailActions(){const cancelled=current==='Detail · cancelled'||currentDetailRecord().status==='Cancelled';return `<div class="detail-actions ${cancelled?'detail-actions-track-again':''}" aria-label="Subscription actions">${cancelled?'<button class="primary" data-track-again>Track again</button>':btn('Edit','Edit','primary')+btn('I cancelled this','Detail · cancelled','secondary')}</div>`;}
const deleteIcon=`<button class="delete-icon danger" data-go="Delete confirm" aria-label="Delete subscription"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 10v7M14 10v7"/></svg></button>`;
function authField(label,value,type,prefix,error=''){
 const name=slug(label),id=`${prefix}-auth-${name}`;
 return `<div class="auth-field"><label for="${id}">${label}</label><input id="${id}" name="${name}" type="${type}" value="${escape(value)}" required ${type==='password'?'minlength="6"':''} aria-invalid="${Boolean(error)}" aria-describedby="${id}-error"><p id="${id}-error" class="field-error" aria-live="polite" ${error?'':'hidden'}>${error}</p></div>`;
}
function validateAuthField(field){
 let message='';const value=field.value.trim();
 if(!value)message=field.name==='name'?'Enter your name.':field.name==='email'?'Enter your email address.':field.name==='confirm-password'?'Confirm your password.':'Enter your password.';
 else if(field.type==='email'&&field.validity.typeMismatch)message='Enter a valid email address.';
 else if(field.name==='confirm-password'&&field.value!==(field.form.elements.password||field.form.elements['new-password']).value)message='Passwords do not match.';
 else if(field.type==='password'&&field.value.length<6)message='Use at least 6 characters.';
 const error=field.parentElement.querySelector('.field-error');error.textContent=message;error.hidden=!message;field.setAttribute('aria-invalid',String(Boolean(message)));return !message;
}
const recoveryIntro=(title,copy,back)=>`<div class="recovery-top">${backButton({attributes:`data-go="${back}"`,label:"Go back",className:"recovery-back"})}<img src="assets/renewless-mark.svg" alt="Renewless"/></div><div class="login-intro recovery-intro"><h2>${title}</h2><p>${copy}</p></div>`;
function validateOtp(form){const fields=[...form.querySelectorAll('.otp input')],valid=fields.every(f=>/^[0-9]$/.test(f.value));const error=form.querySelector('.otp-error');error.hidden=valid;error.textContent=valid?'':'Enter the complete 6-digit code.';fields.forEach(f=>f.setAttribute('aria-invalid',String(!valid)));return valid;}
function auth(up=false){
 const prefix=up?'upgraded':'baseline';
 if(current==='Splash')return `<div class="splash splash-reveal"><svg class="splash-mark" viewBox="0 0 51 51" fill="none" role="img" aria-label="Renewless R logo"><path class="r-upper" pathLength="1" d="M16 19C18 11 26 9 33 13C40 17 40 25 34 29"/><path class="r-lower" pathLength="1" d="M13 40C10 31 14 24 20 27C26 30 30 43 40 39"/></svg><div class="splash-name">Renewless</div><p class="splash-tagline">Stop the subscription renewals<br>you don’t need.</p></div>`;
 if(current==='Login'||current==='Login · error')return `<section class="login-layout"><div class="login-intro">${brand()}<h2>Welcome back</h2><p>Keep your next renewal in sight.</p></div><form class="login-form" data-auth-form novalidate data-submit="Home">${authField('Email','alex@example.com','email',prefix)}${authField('Password','sample123','password',prefix,current.includes('error')?'Wrong email or password. Please try again.':'')}${btn('Forgot password?','Forgot password','login-forgot')}<button class="primary">Log in</button></form><div class="login-divider"><span>or</span></div><div class="login-social">${socialButton('Google')}${socialButton('Apple')}</div><div class="login-signup"><span>New to Renewless?</span>${btn('Sign up','Sign up','signup-link')}</div></section>`;
 if(current==='Sign up')return `<section class="login-layout signup-layout"><div class="login-intro">${brand()}<h2>Create your account</h2><p>Keep your subscriptions in one place.</p></div><form class="login-form" data-auth-form novalidate data-submit="Verify OTP">${authField('Name','Alex Morgan','text',prefix)}${authField('Email','alex@example.com','email',prefix)}${authField('Password','sample123','password',prefix)}${authField('Confirm password','sample123','password',prefix)}<button class="primary">Create account</button></form><div class="login-divider"><span>or</span></div><div class="login-social">${socialButton('Google')}${socialButton('Apple')}</div><div class="login-signup"><span>Already have an account?</span>${btn('Log in','Login','signup-link')}</div></section>`;
 if(current==='Verify OTP'||current==='Verify reset'){
 const reset=current==='Verify reset';
 return `<section class="login-layout recovery-layout">${recoveryIntro(reset?'Check your email':'Verify your email',reset?'Enter the code we sent to reset your password.':'One last step. Enter the code sent to your email.',reset?'Forgot password':'Sign up')}<div class="email-destination"><span>Code sent to</span><strong>alex@example.com</strong>${btn('Change email',reset?'Forgot password':'Sign up','change-email')}</div><form class="login-form otp-form" data-otp-form novalidate data-submit="${reset?'Reset password':'Home'}"><label id="${prefix}-code-label">Verification code</label><div class="otp" role="group" aria-labelledby="${prefix}-code-label">${'481926'.split('').map((v,i)=>`<input aria-label="Digit ${i+1}" aria-describedby="${prefix}-code-error" maxlength="1" pattern="[0-9]" inputmode="numeric" autocomplete="${i===0?'one-time-code':'off'}" value="${v}" required>`).join('')}</div><p id="${prefix}-code-error" class="field-error otp-error" aria-live="polite" hidden></p><p class="code-expiry">Code expires in 5 minutes</p><button class="primary">${reset?'Verify code':'Verify email'}</button></form><div class="resend-area"><p>Didn’t receive a code?</p>${action('Resend code','resend','resend-link')}<small>Available after 2 minutes</small></div></section>`;
 }
 if(current==='Forgot password')return `<section class="login-layout recovery-layout">${recoveryIntro('Forgot password?','No worries. We’ll send a verification code to your email.','Login')}<form class="login-form" data-auth-form novalidate data-submit="Verify reset">${authField('Email','alex@example.com','email',prefix)}<button class="primary">Send code</button></form><div class="login-signup recovery-footer"><span>Remember your password?</span>${btn('Log in','Login','signup-link')}</div></section>`;
 return `<section class="login-layout recovery-layout">${recoveryIntro('Set a new password','Choose a new password to keep your account secure.','Verify reset')}<form class="login-form" data-auth-form novalidate data-submit="Login">${authField('New password','','password',prefix)}<p class="password-hint">Use at least 6 characters.</p>${authField('Confirm password','','password',prefix)}<button class="primary">Reset password</button></form><p class="recovery-note">You’ll log in with your new password.</p></section>`;
}
function home(up){
 if(current==='Home · loading')return homeSkeleton();
 const quiet=current==='Home · quiet';
 let h=heading('Home',false,true);
 if(current==='Home · empty')return h+empty('Your subscriptions, in one place','Add your first subscription to see what renews next.',true);
 const hero=homeNextEvent(quiet);
 return `<div class="home-dashboard">${h}${hero}${homeStats()}${spendingCharts(true)}<div class="home-upcoming-heading"><h3>Upcoming subscriptions</h3><small>Next 7 days</small></div>${quiet?'<p class="note">No renewals scheduled in the next 7 days.</p>':'<div class="rows subscription-rows">'+homeMonthEvents().filter(r=>r.renewal>=calendarToday&&r.renewal<=new Date(Date.parse(calendarToday+'T00:00:00Z')+7*86400000).toISOString().slice(0,10)).map(spendRecordRow).join('')+'</div>'}</div>`;
}
const listSamples=[{name:'Netflix',price:'15.99',renewal:'2026-10-27',estimated:true,category:'Entertainment'},{name:'Spotify',price:'11.99',renewal:'2026-10-29',category:'Entertainment'},{name:'iCloud+',price:'2.99',renewal:'2026-10-30',category:'Storage'},{name:'Notion',price:'10.00',renewal:'',category:'Productivity'},{name:'Figma',price:'15.00',renewal:'',category:'Productivity'}];
const listView={query:'',sort:'renewal',filters:new Set()};
function subscriptionListData(){return allTrackedRecords();}
function subscriptionRowShell(attributes,content,className=""){return `<button class="row ${className}" ${attributes}>${content}</button>`;}
function subscriptionCard(item,options={}){
 const date=item.renewal,days=date?Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(calendarToday+'T00:00:00Z'))/86400000):null;
 const status=options.status||(options.event?(item.trial?{key:'trial',label:days===0?'Trial ends today':'Trial ending'}:item.projected?{key:'active',label:'Projected renewal'}:days===0?{key:'due-today',label:'Due today'}:days>0&&days<=7?{key:'renewing-soon',label:'Renewing soon'}:{key:'active',label:'Scheduled renewal'}):subscriptionStatus(item));
 const relative=days===0?'Today':days===1?'Tomorrow':days<0?'Past date':'In '+days+' days';
 const timing=options.timing!==undefined?options.timing:date?(item.trial?'Trial ends · ':'')+relative+' · '+detailDate(date):item.trialEnded?'Trial ended '+detailDate(item.trialEnd):'';
 const extra=[...(options.plan&&item.plan?[item.plan]:[]),...(options.details||[])];
 const noCharge=options.event&&item.expectedCharge===false,amount=options.amount!==undefined?options.amount:noCharge?'No charge scheduled':(item.currency&&item.currency!=='USD'?item.currency+' ':'$')+Number(item.price).toFixed(2);
 const caption=options.caption!==undefined?options.caption:(item.trial?'After trial · ':'')+(item.cycle||'Monthly');
 return subscriptionRowShell(options.attributes||`data-subscription-card-id="${escape(item.id)}"`,`<span class="avatar">${platformLogo(item.name)}</span><span class="body"><strong>${escape(item.name)}</strong><small class="status-${escape(status.key)}">${escape(status.label)}</small>${timing?`<small>${escape(timing)}</small>`:!date&&!item.trialEnded&&!['cancelled','expired'].includes(status.key)?'<small class="add-date-label">Add renewal date ›</small>':''}${extra.map(line=>`<small>${escape(line)}</small>`).join('')}${item.estimated&&options.estimated!==false?'<span class="list-estimated">Estimated renewal date</span>':''}</span><span class="amount">${escape(amount)}<small>${escape(caption)}</small></span>`,'subscription-card');
}
function listResults(){let items=subscriptionListData().filter(item=>matchesListFilters(item,listView.filters,listView.query));items.sort((a,b)=>listView.sort==='name'?a.name.localeCompare(b.name):listView.sort==='amount'?Number(b.price)-Number(a.price):((a.renewal||'9999').localeCompare(b.renewal||'9999')||a.name.localeCompare(b.name)));return `<p class="list-result-count" role="status">${items.length} ${listView.query?'result':'subscription'}${items.length===1?'':'s'}<span>27 Oct 2026</span></p>${items.length?`<div class="rows subscription-rows">${items.map(item=>subscriptionCard(item,{attributes:`data-list-service="${escape(item.name)}" data-list-id="${escape(item.id)}" aria-label="${escape(item.name)}${item.renewal?' details':' — add renewal date'}"`})).join('')}</div>`:listEmptyState()}`;}
function list(){let h=heading('Subscriptions',false,true);if(current==='List · empty')return h+listEmptyState(true);const data=subscriptionListData(),dated=data.filter(x=>x.renewal).length;return h+`<div class="list-search-tools"><label class="list-search">Search<input data-list-search type="search" placeholder="Search subscriptions" value="${escape(listView.query)}"></label></div>${listFilterControls()}<div class="list-results">${listResults()}</div>`;}
function refreshListResults(){document.querySelectorAll('.list-results').forEach(el=>el.innerHTML=listResults());}

const previewLoginEmail='alex@example.com';
const relatedPreviewRecords=[{id:'netflix-primary',platformId:'netflix',name:'Netflix',price:'15.99',currency:'USD',cycle:'Monthly',category:'Entertainment',renewal:'2026-10-27',start:'2026-09-27',source:'Manual',plan:'Personal plan'},{id:'netflix-family',platformId:'netflix',name:'Netflix',price:'22.99',currency:'USD',cycle:'Monthly',category:'Entertainment',renewal:'2026-11-04',start:'',source:'Gmail',inboxEmail:'alex.family@gmail.com',plan:'Family plan'}];
function currentDetailRecord(){if(current==='Detail · trial')return trackedRecord({id:'spotify',name:'Spotify',price:'11.99',currency:'USD',cycle:'Monthly',category:'Entertainment',source:'Manual',start:'2026-10-24',trialDays:7,autoRenew:true});if(current==='Detail · trial ended')return trackedRecord({id:'spotify',name:'Spotify',price:'11.99',currency:'USD',cycle:'Monthly',category:'Entertainment',source:'Manual',start:'2026-10-01',trialDays:7,autoRenew:false});const saved=state.manual&&state.manual.name.trim()===demoName?state.manual:{};return trackedRecord({id:demoName==='Netflix'?'netflix-primary':demoName.toLowerCase(),platformId:demoName.toLowerCase(),name:demoName,price:demoPrice,currency:'USD',cycle:'Monthly',category:'Other',renewal:'2026-10-27',start:'',source:'Manual',...(allTrackedRecords().find(r=>r.name===demoName)||{}),...saved});}
function detailEmail(record){return record.source==='Gmail'?(record.inboxEmail||'Inbox unavailable'):previewLoginEmail;}
function detailDate(value){return value?new Date(value+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Not set';}
const reminderPreferences=new Map();
function reminderDaysLeft(record){const value=Date.parse(record.renewal+'T00:00:00Z');return Number.isFinite(value)?Math.max(0,Math.round((value-Date.parse('2026-10-27T00:00:00Z'))/86400000)):0;}
function reminderSetting(record){if(record.status==='Cancelled'||record.trialEnded)return {mode:'off',days:0};const saved=reminderPreferences.get(record.id),remaining=reminderDaysLeft(record);if(saved&&(saved.mode==='off'||(saved.mode==='daily'&&remaining>0)||saved.days<=remaining))return saved;return remaining>=3?{mode:'once',days:3}:{mode:'off',days:0};}
function reminderLabel(record){const pref=reminderSetting(record);return pref.mode==='off'?'Off':pref.mode==='daily'?'Every day · last 3 days':pref.days+' day'+(pref.days===1?'':'s')+' before';}
function closeReminderSheet(phone){phone.querySelector('.reminder-overlay')?.remove();phone.querySelectorAll('[data-reminder-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-reminder-inert');});phone.querySelector('[data-action="reminder"]')?.focus();}
function openReminderSheet(trigger){const phone=trigger.closest('.phone'),record=currentDetailRecord(),remaining=reminderDaysLeft(record),pref=reminderSetting(record),id=phone.id+'-reminder';const choice=(value,title,subtitle='',selected=false)=>`<label class="reminder-choice"><input type="radio" name="reminder" value="${value}" ${selected?'checked':''}><span>${title}${subtitle?`<small>${subtitle}</small>`:''}</span></label>`;const presets=[1,2,3,5,7,10,20].filter(days=>days<=remaining),custom=pref.mode==='once'&&!presets.includes(pref.days);const overlay=document.createElement('div');overlay.className='add-overlay reminder-overlay';overlay.innerHTML=`<section class="reminder-sheet" role="dialog" aria-modal="true" aria-labelledby="${id}-title"><div class="handle"></div><header class="add-sheet-header"><div><h3 id="${id}-title">Remind me</h3><p>${remaining?remaining+' days until '+(record.trial?'trial ends':'renewal'):'No advance reminder available'} · ${detailDate(record.renewal)}</p></div><button class="sheet-close" data-close-reminder aria-label="Close reminder settings">×</button></header><form data-reminder-form novalidate data-record-id="${escape(record.id)}" data-remaining="${remaining}"><div class="reminder-options">${choice('off','Off','No reminder for this subscription',pref.mode==='off')}${remaining>0?choice('daily','Every day for the last 3 days','3, 2 and 1 day before '+(record.trial?'trial ends':'renewal'),pref.mode==='daily'):''}${presets.length?`<fieldset><legend>Remind me once</legend><div class="reminder-day-grid">${presets.map(days=>choice(String(days),days+' day'+(days===1?'':'s')+' before','',pref.mode==='once'&&pref.days===days)).join('')}</div></fieldset>`:''}${remaining?`<div class="reminder-custom">${choice('custom','Custom days','Choose between 1 and '+remaining+' days',custom)}<label class="reminder-custom-label" for="${id}-custom">Days before ${record.trial?'trial ends':'renewal'}</label><input id="${id}-custom" name="customDays" type="number" min="1" max="${remaining}" step="1" inputmode="numeric" placeholder="e.g. 4" value="${custom?pref.days:''}" aria-describedby="${id}-error"><p id="${id}-error" class="manual-error" aria-live="polite" hidden></p></div>`:'<p class="reminder-empty">This date is today or has passed. Set a future event date to choose an advance reminder.</p>'}</div><footer class="reminder-save"><button type="submit" class="primary">Save reminder</button><p>Only options that fit before this ${record.trial?'trial ending':'renewal'} are shown.</p></footer></form></section>`;[...phone.children].forEach(el=>{if(!el.inert){el.inert=true;el.dataset.reminderInert='true';}});phone.append(overlay);overlay.querySelector('[data-close-reminder]').focus();}
function detail(up){return subscriptionDetailReview(up);}


let platformOrigin=null;
function platformSubscriptions(){
 const origin=platformOrigin||currentDetailRecord(),fromSpend=!!origin.spendingReturn;
 const others=fromSpend?spendingRecords().filter(r=>r.name===origin.name):allTrackedRecords().filter(r=>r.name===origin.name&&r.id!==origin.id);
 return `<div class="head">${backButton({attributes:`${fromSpend?`data-go="${origin.spendingReturn}"`:'data-platform-back'}`,label:"Go back",className:""})}<h2>${fromSpend?escape(origin.name):'More on '+escape(origin.name)}</h2></div><p class="note">${others.length} ${fromSpend?'':'other '}subscription${others.length===1?'':'s'}</p><div class="rows subscription-rows">${others.map(spendRecordRow).join('')||'<p class="note">No other subscriptions on this platform.</p>'}</div>`;
}

const calendarView={year:2026,month:9,selected:'2026-10-27'};
const calendarToday='2026-10-27';
function calendarRecords(){return allTrackedRecords().filter(r=>(r.renewal||r.trialEnd)&&!['Cancelled','Expired'].includes(r.status));}
function calendarEvents(view=calendarView){const {year,month}=view,first=new Date(Date.UTC(year,month,1)).toISOString().slice(0,10),last=new Date(Date.UTC(year,month+1,1)).toISOString().slice(0,10);return calendarRecords().flatMap(r=>{const end=trialEnd(r),anchor=end||r.renewal,events=[];if(end&&end>=first&&end<last)events.push({...r,renewal:end,trial:true,expectedCharge:r.autoRenew!==false,eventType:'trial-end'});if(end&&r.autoRenew===false)return events;for(let i=end?1:0;i<2400;i++){const date=i===0?anchor:nextCycle(anchor,r.cycle,i);if(date>=last)break;if(date>=first)events.push({...r,renewal:date,trial:false,expectedCharge:true,eventType:'renewal',projected:i>0});}return events;}).sort((a,b)=>a.renewal.localeCompare(b.renewal)||a.name.localeCompare(b.name));}
function calendarTotals(events){const totals={};events.filter(r=>r.expectedCharge!==false).forEach(r=>totals[r.currency]=(totals[r.currency]||0)+Math.round(Number(r.price)*100));return Object.entries(totals).map(([currency,cents])=>`${currency} ${(cents/100).toFixed(2)}`).join(' · ')||'No scheduled charges';}
function calendarEventRows(events){return events.map(r=>subscriptionCard(r,{event:true,plan:true,attributes:`data-calendar-record="${escape(r.id)}" data-event-date="${escape(r.renewal)}" aria-label="View ${escape(r.name)} subscription for ${detailDate(r.renewal)}"`})).join('');}
function calendarScreen(){const events=calendarEvents(),{year,month,selected}=calendarView,monthName=new Date(Date.UTC(year,month,1)).toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}),firstDay=new Date(Date.UTC(year,month,1)).getUTCDay(),days=new Date(Date.UTC(year,month+1,0)).getUTCDate(),cells=Math.ceil((firstDay+days)/7)*7;const selectedEvents=events.filter(r=>r.renewal===selected),upcoming=events.filter(r=>r.renewal>=calendarToday&&r.renewal!==selected);return `<div class="calendar-layout"><div class="head calendar-head"><h2>Calendar</h2>${btn('+','Add sheet','plus')}</div><div class="calendar-month-nav"><button data-calendar-month="-1" aria-label="Previous month">‹</button><details class="calendar-month-picker"><summary aria-label="Choose month and year">${monthName}${selectChevron()}</summary><form data-calendar-picker>${selectField({label:'Month',name:'month',value:month,options:Array.from({length:12},(_,m)=>({value:m,label:new Date(Date.UTC(2026,m,1)).toLocaleDateString('en-GB',{month:'long',timeZone:'UTC'})}))})}<label>Year<input name="year" type="number" min="1900" max="2100" value="${year}" required></label><button class="primary" type="submit">Show month</button></form></details><button data-calendar-month="1" aria-label="Next month">›</button><button class="calendar-today" data-calendar-today>Today</button></div><section class="calendar-month-summary"><div>${infoTooltip({id:'calendar-cost-info',label:'Expected this month',paragraphs:['Expected charges scheduled for the selected month, including projected renewals. This is not a total of payments already made.','Amounts in different currencies are shown separately. Records without renewal dates are excluded; estimated dates and future charges may change.'],className:'calendar-cost-info'})}<strong>${calendarTotals(events)}</strong></div><div class="calendar-month-count"><strong>${events.length}</strong><span>events</span></div></section><section class="calendar-board" aria-label="${monthName} renewal calendar"><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<span>${day}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:cells},(_,i)=>{const day=i-firstDay+1;if(day<1||day>days)return '<span class="calendar-blank" aria-hidden="true"></span>';const date=new Date(Date.UTC(year,month,day)).toISOString().slice(0,10),due=events.filter(r=>r.renewal===date),status=due.length?{key:date===calendarToday?'due-today':date<calendarToday?'past':due.some(r=>r.trial)?'trial':'upcoming'}:null;return `<button class="calendar-day ${due.length?'has-renewal':''} ${date===calendarToday?'is-today':''} ${date===selected?'is-selected':''}" data-calendar-day="${date}" aria-label="${detailDate(date)}, ${due.length} renewal${due.length===1?'':'s'}${due.some(r=>r.trial)?', includes trial ending':''}${date===calendarToday?', today':''}" aria-pressed="${date===selected}"><span>${day}</span>${due.length?`<small class="status-${status.key}"><i></i>${due.length} ${due.every(r=>r.trial)?'trial':'due'}</small>`:'<small class="calendar-no-event" aria-hidden="true">—</small>'}</button>`;}).join('')}</div><div class="calendar-legend"><span class="legend-due"><i></i> Due today</span><span class="legend-upcoming"><i></i> Upcoming</span><span class="legend-trial"><i></i> Trial ending</span><span><b></b> Today</span></div></section>${calendarNextCard(events)}</div>`;}function calendarNextCard(events){const next=events.find(r=>r.renewal>=calendarToday);return next?`<section class="calendar-next"><div class="calendar-section-title"><h3>${next.trial?(next.renewal===calendarToday?'Trial ends today':'Trial ending'):next.renewal===calendarToday?'Due today':'Next renewal'}</h3><span>${detailDate(next.renewal)}</span></div>${calendarEventRows([next])}</section>`:'<section class="calendar-next"><div class="calendar-section-title"><h3>All clear</h3></div><p class="calendar-empty-copy">No upcoming renewals in this month.</p></section>';}
function calendarDayScreen(){const events=calendarEvents().filter(r=>r.renewal===calendarView.selected);return `<div class="head">${btn('‹','Calendar','back')}<h2>${detailDate(calendarView.selected)}</h2></div><p class="note">${events.length?events.length+' scheduled · '+calendarTotals(events):'No renewals scheduled for this day.'}</p>${events.length?`<div class="rows subscription-rows calendar-event-list">${calendarEventRows(events)}</div>`:btn('Add a subscription','Add form')}`;}
function openCalendarRecord(record){state.manual={...(allTrackedRecords().find(r=>r.id===record.id)||record)};demoName=record.name;demoPrice=record.price;go('Detail');}

const manualField=(label,name,type='text',placeholder='')=>`<label>${label}<input name="${name}" type="${type}" placeholder="${placeholder}" ${type==='number'?'min="0.01" step="0.01" inputmode="decimal"':''} required><span class="manual-error" aria-live="polite" hidden></span></label>`;
let manualFormId=0;
const manualServices=[['Netflix','Entertainment','netflix'],['Spotify','Entertainment','spotify'],['iCloud+','Storage','icloud'],['Notion','Productivity','notion',['NOTION LABS']],['Figma','Productivity','figma'],['Duolingo','Education','duolingo'],['YouTube Premium','Entertainment','youtube-premium'],['Apple Music','Entertainment','apple-music'],['Google One','Storage','google-one']];
function manualForm(edit=false){const id='service-options-'+(++manualFormId);return heading(edit?'Edit subscription':'Add subscription',true)+`<form id="${id}-form" class="manual-form manual-compact" data-submit="save-manual" data-edit="${edit}" novalidate><div class="service-search"><label>Platform or service<input name="name" placeholder="Type a service name" required autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}"><span class="manual-error" aria-live="polite" hidden></span></label><div class="service-suggestions" id="${id}" role="listbox" aria-label="Matching services" hidden></div></div><div class="manual-price-row">${manualField('Amount','price','number','0.00')}${selectField({label:'Currency',name:'currency',options:['USD', 'EUR', 'GBP', 'PKR', 'AED', 'INR']})}</div><div class="manual-pair">${selectField({label:'Billing cycle',name:'cycle',options:['Monthly', 'Quarterly', 'Yearly', 'Weekly']})}${selectField({label:'Category',name:'category',options:['Entertainment', 'Productivity', 'Education', 'Storage', 'Utilities', 'Other']})}</div>${trialFields()}<div class="manual-pair manual-dates"><label>Start date <small>Optional</small><input type="date" name="start"><span class="manual-error" aria-live="polite" hidden></span></label>${manualField('Next renewal','renewal','date')}</div>${trialFormSummary()}<label>Notes <small>Optional</small><textarea name="note" rows="2" maxlength="500" placeholder="Anything you’d like to remember"></textarea></label><div class="manual-save"><button class="primary" type="submit" form="${id}-form">${edit?'Save changes':'Add subscription'}</button><p>You can edit these details anytime.</p></div></form>`;}
function closeServiceSuggestions(form){const list=form.querySelector('.service-suggestions');list.hidden=true;form.elements.name.setAttribute('aria-expanded','false');form.elements.name.removeAttribute('aria-activedescendant');}
function showServiceSuggestions(field){const form=field.form,list=form.querySelector('.service-suggestions'),q=field.value.trim().toLowerCase();const matches=q?manualServices.filter(([name])=>name.toLowerCase().includes(q)).slice(0,4):[];list.innerHTML=matches.map(([name,category],i)=>`<button type="button" role="option" aria-selected="false" id="${list.id}-${i}" data-service="${escape(name)}" data-category="${category}"><span>${escape(name)}</span><small>${category}</small></button>`).join('');list.hidden=!matches.length;field.setAttribute('aria-expanded',String(!!matches.length));field.removeAttribute('aria-activedescendant');}
function selectService(button){const form=button.closest('form'),field=form.elements.name;field.value=button.dataset.service;form.elements.category.value=button.dataset.category;syncSelectControls();field.setAttribute('aria-invalid','false');field.nextElementSibling.hidden=true;closeServiceSuggestions(form);field.focus();}

function validateManual(form){let valid=validateTrialForm(form);for(const input of form.querySelectorAll('input[required]')){let message='';if(!input.value.trim())message=({name:'Enter a platform or service name.',price:'Enter the subscription amount.',renewal:'Choose the next renewal date.',start:'Select a start date to calculate your trial end date.',trialDaysCustom:'Enter your trial duration.'})[input.name];else if(input.name==='trialDaysCustom'&&(!Number.isInteger(Number(input.value))||Number(input.value)<1||Number(input.value)>365))message='Enter a whole number from 1 to 365.';else if(input.name==='price'&&(!Number.isFinite(Number(input.value))||Number(input.value)<=0||!input.validity.valid))message='Enter a valid amount greater than 0 (up to 2 decimals).';input.setAttribute('aria-invalid',String(!!message));const error=input.nextElementSibling;error.textContent=message;error.hidden=!message;if(message)valid=false;}return valid;}
function addForm(edit){return manualForm(edit);}
function chat(up){return aiTextScreen();}
function gmail(){return authenticatedGmailScreen();}
function profile(up){return profileScreen();}
function renderBody(up){
 if(current.startsWith('Connected inbox'))return connectedInboxScreen();
 if(current==='Inbox subscriptions')return inboxSubscriptionsScreen();
 if(current==='Edit profile')return profileEditScreen();
 if(current==='Change password')return changePasswordScreen();
 if(current.startsWith('Alerts'))return alertsScreen();
 if(current==='Reminder settings')return reminderSettingsScreen();
 if(current==='Widgets')return widgetHomeScreen();
 if(current.startsWith('Payments'))return paymentsScreen();

 if(current==='Trial review')return authenticatedGmailScreen();
 if(current==='Spending breakdown')return spendingBreakdown();
 if(current==='This month')return monthBreakdown();
 if(current==='Calendar')return calendarScreen();
 if(current==='Calendar day')return calendarDayScreen();
 if(onboardingScreens.includes(current))return onboarding();
 if(groups.Auth.includes(current))return auth(up);
 if(current.startsWith('Home'))return home(up);
 if(current.startsWith('List'))return list();
 if(current==='Platform subscriptions')return platformSubscriptions();
 if(current.startsWith('Detail'))return detail(up);
 if(current==='Add form'||current==='Edit')return addForm(current==='Edit');
 if(current==='Add sheet')return `<div class="add-sheet-background" inert aria-hidden="true">${previous==='Calendar'?calendarScreen():heading('Home',false,true)+stats()}</div><div class="add-overlay"><section class="add-sheet" role="dialog" aria-modal="true" aria-labelledby="add-title-${up?'final':'base'}"><div class="handle"></div><header class="add-sheet-header"><div><h3 id="add-title-${up?'final':'base'}">Add a subscription</h3><p>Choose what works for you.</p></div><button class="sheet-close" data-go="back" aria-label="Close add subscription"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="add-options"><button class="add-option add-option-ai" data-go="AI chat"><span class="add-option-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z"/></svg></span><span class="add-option-copy"><strong>Add with AI</strong><small>Type, speak, or share a screenshot</small></span><span class="add-chevron" aria-hidden="true">›</span></button><button class="add-option" data-go="Add form"><span class="add-option-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 4 5 5M4 20l5-1L21 7l-4-4L5 15z"/></svg></span><span class="add-option-copy"><strong>Add manually</strong><small>Enter your subscription details</small></span><span class="add-chevron" aria-hidden="true">›</span></button><button class="add-option" data-go="Gmail · scanning"><span class="add-option-icon">${platformLogo('Gmail')}</span><span class="add-option-copy"><strong>Connect Gmail</strong><small>Find subscriptions in your inbox</small></span><span class="add-chevron" aria-hidden="true">›</span></button></div></section></div>`;
 if(current.startsWith('AI chat')||current==='Voice')return chat(up);
 if(current.startsWith('Gmail'))return gmail();
 if(current==='Delete confirm')return heading('Detail',true)+`<div class="overlay"><div class="sheet"><h3>Delete subscription?</h3><p>This removes it from Renewless. It does not cancel the real service.</p>${action('Delete from Renewless','delete','primary')}${btn('Keep subscription','Detail','secondary')}</div></div>`;
 if(current==='Alerts · empty')return heading('Alerts')+empty('No alerts yet','Reminders show up here after they are sent.');
 if(current.startsWith('Profile'))return profile(up);


 if(current.startsWith('History'))return historyScreen();
 if(current.startsWith('Payments'))return heading('Payments',true)+(current.includes('empty')?empty('No charges yet','This stays empty until a tracked charge is available.',false,false):panel('<span class="metric-label">Paid so far · USD</span><p class="hero-price">$1,019</p><small>Estimated from your tracked subscriptions</small>')+(up?spendingCharts(true):'')+'<h3>This month <small style="float:right">$86</small></h3>'+rows()+'<p class="note">Amounts are grouped by currency. No currency conversion.</p>');
 return '';
}
function isTab(){return /^(Home|List|Calendar|Alerts|Profile)( ·|$)/.test(current)}
function render(){closeSelectMenu(false);
 const authFinal=isAiChatScreen()||current==='Widgets'||current.startsWith('Gmail ·')||current==='Delete confirm'||current.startsWith('Detail')||current.startsWith('Payments')||current.startsWith('History')||current.startsWith('Profile')||['Edit profile','Inbox subscriptions','Change password'].includes(current)||current.startsWith('Connected inbox')||groups.Alerts.includes(current)||groups.Auth.includes(current)||onboardingScreens.includes(current)||current.startsWith('Home')||current.startsWith('List')||['Add sheet','Add form','Edit','List','List · trial','List · trial ended','Alerts · trial','Trial review','AI chat · trial','Detail','Detail · trial','Detail · trial ended','Calendar','Calendar day','Spending breakdown','This month','Platform subscriptions'].includes(current);
 const comparison=document.getElementById('comparison'),mode=document.getElementById('mode');
 comparison.dataset.mode=authFinal?'upgraded':mode.value;
 mode.hidden=authFinal;
 comparison.querySelector('[data-variant="baseline"]').hidden=authFinal;
 const title=comparison.querySelector('[data-variant="upgraded"] .variant-title');
 title.querySelector('h2').textContent=authFinal?'Final':'Upgraded UI';
 title.querySelector('span').textContent=authFinal?'01':'02';
 title.querySelector('small').textContent=authFinal?'Final design':'Same flow · clearer hierarchy';
 document.querySelector('.footnote').textContent=authFinal?'Interactive final design preview. All connections, scans and purchases use fictional data.':'Baseline reconstructed from reviewed Figma screens and locked specs; not a pixel-exact export. Browser glass approximates the intended native material. Public prototype uses fictional data.';
 document.getElementById('title').textContent=current;
 document.getElementById('context').textContent=authFinal?'Final design. Choose a screen or tap through the phone. Onboarding connections and scans are simulated.':'Compare the same screen and state. Use the screen library or tap through the phone controls; both versions stay in sync.';
 for(const id of ['baseline','upgraded']){const p=document.getElementById(id);if(authFinal&&id==='baseline'){p.innerHTML='';continue;}p.innerHTML=`<div class="status"><span>9:41</span><span class="island"></span><span>▂▄▆ ▰</span></div><div class="content ${isTab()?'has-tabs':''} ${isAiChatScreen()?'ai-text-content':''} ${current==='Widgets'?'widget-preview-content':''} ${(current.startsWith('Gmail ·')||current==='Trial review')?'gmail-review-content':''} ${current==='Calendar'||(current==='Add sheet'&&previous==='Calendar')?'calendar-content':''} ${current==='Splash'?'splash-content':''} ${current==='Reminder settings'?'reminder-settings-content':''} ${current==='Change password'?'password-change-content':''} ${(current==='Add form'||current==='Edit')?'has-manual-footer':''} ${id==='upgraded'&&current.startsWith('Detail')?'has-detail-actions':''}">${renderBody(id==='upgraded')}</div>${id==='upgraded'&&current.startsWith('Detail')?detailActions():''}${isTab()?tabs():''}<div class="homebar"></div>`;if(current.startsWith('Gmail ·')||current==='Trial review'){const footer=p.querySelector('.gmail-review-footer');if(footer)p.append(footer);}if(current==='Reminder settings')p.append(p.querySelector('.reminder-settings-footer'));if(current==='Change password'){const footer=p.querySelector('.password-change-footer');if(footer)p.append(footer);}if(current==='Add form'||current==='Edit'){p.append(p.querySelector('.manual-save'));if(current==='Edit'){const values=state.manual&&state.manual.name.trim()===demoName?state.manual:{name:demoName,price:demoPrice,currency:'USD',cycle:'Monthly',category:manualServices.find(([name])=>name===demoName)?.[1]||'Other',start:'2026-09-27',renewal:'2026-10-27',note:''};const form=p.querySelector('.manual-form');for(const [key,value] of Object.entries(values)){if(form.elements.namedItem(key))form.elements.namedItem(key).value=value;}}initTrialForm(p.querySelector('.manual-form'),current==='Edit'?state.manual:null);}}syncSelectControls();renderNav();onboardingAfterRender();gmailAfterRender();widgetPreviewAfterRender();aiTextAfterRender();if(current.startsWith('Gmail ·')||current==='Trial review'){document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.querySelector('[data-variant=upgraded] .variant-title h2').textContent='Final';document.querySelector('.footnote').textContent='Interactive final design preview. Connections and scans are fictional; selected records save only in browser memory.';document.getElementById('context').textContent='Final authenticated Gmail family · approved scanning, review, sheets and recovery. Fictional scan/results and local saves; no live OAuth, Gmail/AI or payment processing.';}if(current.startsWith('Profile')||['Edit profile','Inbox subscriptions','Change password'].includes(current)||current.startsWith('Connected inbox')){const approved=screenDesignLocks[current]==='locked';document.querySelector('[data-variant=upgraded] .variant-title small').textContent=approved?'Final design · locked':'Design review';document.getElementById('context').textContent=approved?(current==='Change password'?'Final Change password · approved design. Tap through the controls.':current.startsWith('Connected inbox')||current==='Inbox subscriptions'?'Final Connected inbox · approved connection states and imported subscriptions.':'Final Profile & Edit profile · approved design. Tap through the controls.'):'Profile · account, inboxes and preferences. Review the design and tap through the controls.';}if(current.startsWith('Detail')||['Platform subscriptions','Delete confirm'].includes(current)){document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.getElementById('context').textContent='Final Detail family · approved billing, Gmail receipt history, reminders, Track again and related views. Sync is not live in this prototype.';}if(current.startsWith('Payments')){document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.getElementById('context').textContent='Final Payments · approved Gmail receipt history, period filters, six-month chart and empty states. Preview uses fictional receipts.';}if(current.startsWith('History')){document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.getElementById('context').textContent='Final History · approved status filters, compact spacing and empty state.';}if(groups.Alerts.includes(current)){document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.getElementById('context').textContent='Final Alerts & reminder settings · approved design. Tap through the controls.';}trialFormAfterRender();}
const screenDesignLocks={"AI chat · attachment":"base","Splash":"base","Login":"base","Login · error":"base","Sign up":"base","Verify OTP":"base","Forgot password":"base","Verify reset":"base","Reset password":"base","Welcome":"base","Connect inbox":"base","Inbox permission":"base","Discovering":"base","Your subscriptions":"base","Save your finds":"base","Ready to go":"base","Scan · no results":"base","Scan · interrupted":"base","Home":"base","Home · loading":"base","Home · empty":"base","Home · quiet":"base","Spending breakdown":"base","This month":"base","Calendar":"base","Calendar day":"base","List":"base","List · empty":"base","List · upcoming":"base","List · no renewal":"base","List · active":"base","List · trial":"base","List · trial ended":"base","List · due today":"base","List · cancelled":"base","List · expired":"base","Alerts":"base","Alerts · trial":"base","Alerts · empty":"base","Alerts · notifications off":"base","Reminder settings":"base","Profile":"base","Profile · incomplete":"base","Profile · social":"base","Edit profile":"base","Change password":"base","History":"base","History · empty":"base","Payments":"base","Payments · empty":"base","Connected inbox":"base","Connected inbox · reconnect":"base","Connected inbox · syncing":"base","Connected inbox · error":"base","Inbox subscriptions":"base","Detail":"base","Detail · trial":"base","Detail · trial ended":"base","Detail · cancelled":"base","Detail · no renewal":"base","Platform subscriptions":"base","Delete confirm":"base","Gmail · scanning":"base","Gmail · review":"base","Trial review":"base","Gmail · nothing found":"base","Gmail · interrupted":"base","Widgets":"base","AI chat":"base","AI chat · trial":"base","Voice":"base","Add sheet":"base","Add form":"base","Edit":"base"};
const studioLockBadge=name=>{const lock=screenDesignLocks[name];if(!lock)return '';const label=lock==='base'?'Base design locked; typography pending review':'Design locked';return `<span class="studio-lock ${lock==='base'?'studio-lock-base':''}" role="img" aria-label="${label}" title="${label}">${lock==='base'?'<span class="studio-lock-base-label">Base</span>':''}<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="4.5" y="8.5" width="11" height="8" rx="2"/><path d="M6.5 8.5V6a3.5 3.5 0 0 1 7 0v2.5M10 12v1.5"/></svg></span>`;};
function renderNav(){const q=document.getElementById('search').value.toLowerCase();document.getElementById('screens').innerHTML=Object.entries(groups).map(([group,names])=>{const found=names.filter(s=>s.toLowerCase().includes(q));return found.length?`<section><h3>${group}</h3>${found.map(s=>`<button class="${s===current?'active':''}" data-go="${escape(s)}" ${s===current?'aria-current="page"':''}><span class="studio-screen-name">${escape(s)}</span>${studioLockBadge(s)}</button>`).join('')}</section>`:'';}).join('');}
function go(name){name=({'AI chat · image':'AI chat · attachment','Paywall':'Home','Profile · Pro':'Profile'})[name]||name;if(name==='Home'&&ob.pending&&groups.Auth.includes(current)){ob.account=true;ob.pending=false;name='Ready to go';}if(name==='Gmail · scanning'&&current!==name){if(!current.startsWith('Gmail ·')&&current!=='Trial review'){gmailReview.origin=isTab()?current:'List';gmailReview.intent=profileInboxes.length?'sync':'first';}beginAuthenticatedGmailScan();}if(name==='Payments · empty'||(name==='Payments'&&!current.startsWith('Detail')&&!current.startsWith('Payments'))){paymentsView.recordId='';paymentsView.recordName='';paymentsView.detailOrigin='';}if(name==='Edit'&&current.startsWith('Detail')){state.manual={...currentDetailRecord()};demoName=state.manual.name;demoPrice=state.manual.price;}if(name==='Detail · cancelled'){const r=currentDetailRecord();r.status='Cancelled';trialRecords.set(recordKey(r),r);state.manual=r;reminderPreferences.delete(recordKey(r));}if(name==='back')name=previous===current?'Home':previous;if(!screens.includes(name))return;seedListFilters(name);if(name==='Welcome'){ob.account=false;ob.pending=false;}if(name==='Sign up'&&onboardingScreens.includes(current))ob.pending=true;if(name==='Discovering'&&current!==name)ob.scan=0;previous=current;current=name;history.replaceState(null,'','#'+slug(name));render();}
let toastTimer;function toast(s){const t=document.getElementById('toast');t.textContent=s;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4000);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){if(b.dataset.name)demoName=b.dataset.name;if(b.dataset.price)demoPrice=b.dataset.price;go(b.dataset.go);}else if(b.dataset.month){const chart=b.closest('.chart-card');chart.querySelectorAll('[data-month]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});chart.querySelector('.chart-selection').textContent=b.dataset.month+' · '+(b.dataset.currency||'USD')+' '+b.dataset.value+' expected';}else if(b.dataset.cycle){state.cycle=b.dataset.cycle;document.querySelectorAll('[data-cycle]').forEach(x=>x.classList.toggle('selected',x.dataset.cycle===state.cycle));}else if(b.dataset.history){document.querySelectorAll('[data-history]').forEach(x=>x.classList.toggle('selected',x.dataset.history===b.dataset.history));document.querySelectorAll('.phone .row').forEach(x=>x.hidden=b.dataset.history!=='All'&&!x.textContent.includes(b.dataset.history));}else if(b.dataset.action){switch(b.dataset.action){case 'reminder':openReminderSheet(b);break;case 'loop':if(!matchMedia('(prefers-reduced-motion: reduce)').matches)b.animate([{transform:'rotate(0)'},{transform:'rotate(-7deg)'},{transform:'rotate(0)'}],{duration:400});break;case 'keep':toast('Your subscription is unchanged.');break;case 'cancel-intent':toast('Cancel on the service, then record it in Renewless.');break;case 'create-ai':demoName='Duolingo';demoPrice='9.99';state.manual={name:'Duolingo',price:'9.99',source:'AI',currency:'USD',cycle:'Monthly',category:'Education',renewal:'2026-10-20',start:'',note:''};state.manual.id=recordKey(state.manual);trialRecords.set(state.manual.id,{...state.manual});state.created=true;go('Detail');toast('Subscription added.');break;case 'delete':{const r=currentDetailRecord();trialRecords.set(recordKey(r),{...r,status:'Deleted'});reminderPreferences.delete(recordKey(r));}go('List');toast('Subscription removed.');break;case 'dismiss':go('Profile');break;case 'attach':b.closest('.content').querySelector('.attachment').click();break;case 'legal':toast('This page is currently unavailable. Please try again later.');break;case 'resend':toast('You can request a new code after 2 minutes.');break;}}});
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-submit]');if(!form)return;e.preventDefault();if(form.matches('[data-otp-form]')&&!validateOtp(form)){form.querySelector('.otp input').focus();return;}if(form.matches('[data-auth-form]')){const fields=[...form.querySelectorAll('input')];const valid=fields.map(validateAuthField);if(valid.includes(false)){fields[valid.indexOf(false)].focus();return;}}const destination=form.dataset.submit;if(destination==='save-manual'){if(!validateManual(form)){form.querySelector('[aria-invalid="true"]').focus();return;}demoName=form.elements.name.value.trim();demoPrice=Number(form.elements.price.value).toFixed(2);state.manual={...(form.dataset.edit==='true'?state.manual||{}:{source:'Manual'}),...Object.fromEntries(new FormData(form))};storeTrialForm(form);state.created=true;go('Detail');toast(form.dataset.edit==='true'?'Changes saved.':'Subscription added.');}else if(destination==='save-sub'){demoName=form.elements.name.value;demoPrice=Number(form.elements.price.value).toFixed(2);state.created=true;go('Detail');toast('Subscription saved.');}else if(destination==='chat'){toast('Unable to send your message. Please try again.');}else if(destination==='gmail'){if(!form.querySelector('input:checked'))return toast('Select at least one subscription.');state.scannedNames=[...form.querySelectorAll('input:checked')].map(input=>input.closest('label').querySelector('span').firstChild.textContent.trim());go('List');toast('Subscriptions saved.');}else{const passwords=form.querySelectorAll('input[type=password]');if(passwords.length>1&&passwords[passwords.length-1].value!==passwords[passwords.length-2].value)return toast('Passwords do not match.');if(destination==='Home'&&ob.pending){ob.account=true;ob.pending=false;go('Ready to go');}else go(destination);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-search-rows]')){const q=e.target.value.toLowerCase();e.target.closest('.content').querySelectorAll('.row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}});
document.addEventListener('change',e=>{if(e.target.matches('.attachment')&&e.target.files.length)toast('Image selected locally. This prototype does not upload or analyze it.');});
document.getElementById('search').oninput=renderNav;
document.getElementById('mode').onchange=e=>document.getElementById('comparison').dataset.mode=e.target.value;
document.getElementById('reset').onclick=()=>{resetAiTextChats();widgetPreview.mode='next';resetAuthenticatedGmail();resetProfilePreview();resetAccountReminders();trialRecords.clear();paymentRecords.clear();reminderPreferences.clear();listView.filters.clear();listView.query='';listView.sort='renewal';ob.selected=new Set([0,1,2]);ob.account=false;ob.pending=false;ob.scan=0;state.reminder=true;state.cycle='Monthly';state.created=false;state.manual=null;demoName='Netflix';demoPrice='15.99';go('Home');toast('Demo reset.');};
const retiredRouteTargets={'#ai-chat-image':'AI chat · attachment','#home-first-visit':'Home','#home-money':'Home','#paywall':'Home','#profile-pro':'Profile'};
window.addEventListener('hashchange',()=>{if(retiredRouteTargets[location.hash]){go(retiredRouteTargets[location.hash]);return;}const name=screens.find(s=>slug(s)===location.hash.slice(1));if(name)go(name);});
if(retiredRouteTargets[location.hash])history.replaceState(null,'','#'+slug(retiredRouteTargets[location.hash]));
current=screens.find(s=>slug(s)===location.hash.slice(1))||'Splash';seedListFilters(current);render();

// Validate on blur, then revalidate corrected fields without interrupting typing elsewhere.
document.addEventListener('focusout',e=>{if(e.target.matches('[data-auth-form] input')){e.target.dataset.touched='true';validateAuthField(e.target);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-auth-form] input')&&(e.target.dataset.touched||e.target.getAttribute('aria-invalid')==='true'))validateAuthField(e.target);});

document.addEventListener('input',e=>{if(e.target.matches('[data-auth-form] input[name="password"], [data-auth-form] input[name="new-password"]')){const confirm=e.target.form.elements['confirm-password'];if(confirm&&(confirm.dataset.touched||confirm.getAttribute('aria-invalid')==='true'))validateAuthField(confirm);}});

document.addEventListener('input',e=>{if(!e.target.matches('.otp-form .otp input'))return;const field=e.target;field.value=field.value.replace(/[^0-9]/g,'').slice(-1);if(field.value)field.nextElementSibling?.focus();if(!field.closest('form').querySelector('.otp-error').hidden)validateOtp(field.closest('form'));});
document.addEventListener('keydown',e=>{if(e.target.matches('.otp-form .otp input')&&e.key==='Backspace'&&!e.target.value)e.target.previousElementSibling?.focus();});
document.addEventListener('paste',e=>{if(!e.target.matches('.otp-form .otp input'))return;const digits=e.clipboardData.getData('text').replace(/[^0-9]/g,'').slice(0,6);if(!digits)return;e.preventDefault();const fields=[...e.target.closest('.otp').querySelectorAll('input')];fields.forEach((f,i)=>f.value=digits[i]||'');fields[Math.min(digits.length,5)].focus();if(!e.target.closest('form').querySelector('.otp-error').hidden)validateOtp(e.target.closest('form'));});

document.addEventListener('click',e=>{const pick=e.target.closest('[data-service]');if(pick)selectService(pick);else document.querySelectorAll('.manual-compact').forEach(form=>{if(!e.target.closest('.service-search'))closeServiceSuggestions(form);});});
document.addEventListener('input',e=>{const form=e.target.closest('.manual-form');if(!form)return;if(e.target.name==='name')showServiceSuggestions(e.target);if(e.target.getAttribute('aria-invalid')==='true'){e.target.setAttribute('aria-invalid','false');e.target.nextElementSibling.hidden=true;}});
document.addEventListener('keydown',e=>{const field=e.target;if(!field.matches('.manual-compact input[name="name"]'))return;const form=field.form,list=form.querySelector('.service-suggestions');if(e.key==='Escape'){closeServiceSuggestions(form);return;}if(list.hidden)return;const options=[...list.querySelectorAll('[data-service]')];let i=options.findIndex(x=>x.id===field.getAttribute('aria-activedescendant'));if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();i=(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((x,n)=>x.setAttribute('aria-selected',String(n===i)));field.setAttribute('aria-activedescendant',options[i].id);}else if(e.key==='Enter'&&i>=0){e.preventDefault();selectService(options[i]);}else if(e.key==='Tab')closeServiceSuggestions(form);});

document.addEventListener('input',e=>{if(!e.target.matches('[data-list-search]'))return;listView.query=e.target.value;document.querySelectorAll('[data-list-search]').forEach(field=>{if(field!==e.target)field.value=listView.query;});refreshListResults();});
document.addEventListener('change',e=>{if(!e.target.matches('[data-list-sort]'))return;listView.sort=e.target.value;document.querySelectorAll('[data-list-sort]').forEach(field=>field.value=listView.sort);refreshListResults();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-list-service]');if(!button)return;const item=subscriptionListData().find(x=>x.id===button.dataset.listId);demoName=item.name;demoPrice=item.price;state.manual={currency:'USD',cycle:'Monthly',start:'',note:'',source:'Manual',...item,...(state.scannedNames?.includes(item.name)?{source:'Gmail',inboxEmail:'alex.receipts@gmail.com'}:{})};go(item.renewal||item.trialEnded?'Detail':'Edit');});

document.addEventListener('click',e=>{const target=e.target.closest('[data-related-id]');if(!target)return;const record=relatedPreviewRecords.find(r=>r.id===target.dataset.relatedId);if(!record)return;state.manual={...record};demoName=record.name;demoPrice=record.price;go('Detail');});

document.addEventListener('click',e=>{if(e.target.closest('[data-open-platform]')){platformOrigin={...currentDetailRecord()};go('Platform subscriptions');}else if(e.target.closest('[data-platform-back]')){if(platformOrigin){state.manual={...platformOrigin};demoName=platformOrigin.name;demoPrice=platformOrigin.price;}go('Detail');}});

document.addEventListener('click',e=>{const close=e.target.closest('[data-close-reminder]');if(close)closeReminderSheet(close.closest('.phone'));if(e.target.matches('.reminder-overlay'))closeReminderSheet(e.target.closest('.phone'));});
document.addEventListener('input',e=>{if(e.target.name!=='customDays')return;const form=e.target.closest('[data-reminder-form]');if(!form)return;form.querySelector('input[value="custom"]').checked=true;e.target.setAttribute('aria-invalid','false');form.querySelector('.manual-error').hidden=true;});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-reminder-form]');if(!form)return;e.preventDefault();const selected=form.querySelector('input[name="reminder"]:checked').value,remaining=Number(form.dataset.remaining);const days=selected==='off'?0:selected==='daily'?3:selected==='custom'?Number(form.elements.customDays.value):Number(selected);if(selected!=='off'&&(!Number.isInteger(days)||days<1||days>remaining)){const field=form.elements.customDays,error=form.querySelector('.manual-error');error.textContent='Enter a whole number between 1 and '+remaining+'.';error.hidden=false;field.setAttribute('aria-invalid','true');field.focus();return;}reminderPreferences.set(form.dataset.recordId,{mode:selected==='off'?'off':selected==='daily'?'daily':'once',days});const phone=form.closest('.phone');closeReminderSheet(phone);document.querySelectorAll('[data-action="reminder"]').forEach(button=>button.textContent=reminderLabel(currentDetailRecord())+' ›');});
document.addEventListener('keydown',e=>{const overlay=e.target.closest('.reminder-overlay');if(!overlay)return;if(e.key==='Escape'){e.preventDefault();closeReminderSheet(overlay.closest('.phone'));}else if(e.key==='Tab'){const focusable=[...overlay.querySelectorAll('button,input')].filter(el=>!el.disabled);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});

document.addEventListener('click',e=>{const month=e.target.closest('[data-calendar-month]'),today=e.target.closest('[data-calendar-today]'),day=e.target.closest('[data-calendar-day]'),record=e.target.closest('[data-calendar-record]');if(month){const date=new Date(Date.UTC(calendarView.year,calendarView.month+Number(month.dataset.calendarMonth),1));calendarView.year=date.getUTCFullYear();calendarView.month=date.getUTCMonth();calendarView.selected=calendarEvents()[0]?.renewal||date.toISOString().slice(0,10);render();}else if(today){calendarView.year=2026;calendarView.month=9;calendarView.selected=calendarToday;render();}else if(day){calendarView.selected=day.dataset.calendarDay;const events=calendarEvents().filter(r=>r.renewal===calendarView.selected);if(events.length===1)openCalendarRecord(events[0]);else if(events.length===0)go('Add sheet');else go('Calendar day');}else if(record){const item=calendarEvents().find(r=>r.id===record.dataset.calendarRecord&&r.renewal===record.dataset.eventDate);if(item)openCalendarRecord(item);}});

document.addEventListener('submit',event=>{const form=event.target.closest('[data-calendar-picker]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;calendarView.year=Number(form.elements.year.value);calendarView.month=Number(form.elements.month.value);calendarView.selected=calendarEvents()[0]?.renewal||new Date(Date.UTC(calendarView.year,calendarView.month,1)).toISOString().slice(0,10);render();});
document.addEventListener('keydown',event=>{if(event.defaultPrevented)return;if(event.key==='Escape'){const picker=document.querySelector('.calendar-month-picker[open]');if(picker){picker.open=false;picker.querySelector('summary').focus();}}});
document.addEventListener('click',event=>{if(!event.target.closest('.calendar-month-picker, .select-menu-overlay'))document.querySelectorAll('.calendar-month-picker[open]').forEach(picker=>picker.open=false);});

function spendingRecords(){return allTrackedRecords().filter(r=>!['Cancelled','Expired'].includes(r.status));}

function monthlyPlatforms(){const groups=new Map();for(const r of spendingRecords().filter(r=>!r.trial&&!r.trialEnded)){const currency=r.currency||'USD',key=currency+'|'+r.name;const item=groups.get(key)||{name:r.name,currency,value:0,count:0};item.value+=Number(r.price)*({Monthly:1,Quarterly:1/3,Yearly:1/12,Weekly:52/12}[r.cycle]||1);item.count++;groups.set(key,item);}return [...groups.values()].sort((a,b)=>b.value-a.value);}
function spendRow(item,total,origin){return `<button class="spend-platform" ${item.other?'data-go="Spending breakdown"':`data-spend-platform="${escape(item.name)}" data-spend-origin="${origin}"`}><span class="avatar">${item.other?'•••':platformLogo(item.name)}</span><span class="spend-label"><strong>${escape(item.name)}</strong><span class="spend-track"><i style="width:${(total?Math.round(item.value/total*100):0)}%"></i></span><small>${item.other?item.count+' platforms':item.count+' subscription'+(item.count===1?'':'s')}</small></span><span class="spend-value">${item.currency} ${item.value.toFixed(2)}<small>${(total?Math.round(item.value/total*100):0)}% ›</small></span></button>`;}
function spendingSections(compact=false){const platforms=monthlyPlatforms(),currencies=[...new Set(platforms.map(r=>r.currency))];return currencies.map(currency=>{const items=platforms.filter(r=>r.currency===currency),total=items.reduce((n,r)=>n+r.value,0);let shown=compact?items.slice(0,3):items;if(compact&&items.length>3)shown=[...shown,{name:'Others',other:true,count:items.length-3,currency,value:items.slice(3).reduce((n,r)=>n+r.value,0)}];return `<div class="spend-currency"><p class="note">${currency} ${total.toFixed(2)} estimated/month</p>${shown.map(r=>spendRow(r,total,compact?'Home':'Spending breakdown')).join('')}</div>`;}).join('')||'<p class="note">Add subscriptions to see your top spending.</p>';}
function topSpendingCard(){return `<section class="panel top-spending"><div class="spend-heading"><h3>Top spending</h3>${btn('View all ›','Spending breakdown','link')}</div><p class="note">Estimated monthly spend</p>${spendingSections(true)}${trialSpendingSummary()}</section>`;}
function homeMonthEvents(){const [year,month]=calendarToday.split('-').map(Number);return calendarEvents({year,month:month-1});}
function homeMonthCard(){const events=homeMonthEvents(),remaining=events.filter(r=>r.renewal>=calendarToday),percent=events.length?Math.round(remaining.length/events.length*100):0;return `<button class="panel month-overview" data-go="This month"><span class="spend-heading"><strong>This month</strong><span>View details ›</span></span><span class="note">Still expected this month</span><strong class="remaining-total">${remaining.length?calendarTotals(remaining):'No more renewals scheduled'}</strong><span class="month-progress" aria-hidden="true"><i style="width:${percent}%"></i></span><span class="note">${remaining.filter(r=>r.expectedCharge!==false).length} charge${remaining.filter(r=>r.expectedCharge!==false).length===1?'':'s'} remaining${remaining.some(r=>r.trial&&r.expectedCharge===false)?' · '+remaining.filter(r=>r.trial&&r.expectedCharge===false).length+' trial ending without a charge':''}</span><span class="month-full-total">Expected total · ${calendarTotals(events)}</span></button>`;}
function spendRecordRow(r){return subscriptionCard(r,{event:current!=='Platform subscriptions',plan:true,attributes:`data-spend-record="${escape(r.id)}" ${r.renewal?`data-spend-date="${escape(r.renewal)}"`:''} aria-label="View ${escape(r.name)} subscription"`});}
function spendingBreakdown(){return `<div class="head">${btn('‹','Home','back')}<h2>Spending breakdown</h2></div><p class="note">Platforms ranked by estimated monthly spend. Quarterly and yearly plans are averaged per month; currencies stay separate.</p>${spendingSections()}${trialSpendingSummary()}`;}
function monthBreakdown(){const all=homeMonthEvents(),upcoming=all.filter(r=>r.renewal>=calendarToday),earlier=all.filter(r=>r.renewal<calendarToday);return `<div class="head">${btn('‹','Home','back')}<h2>This month</h2></div><p class="note">${new Date(calendarToday+'T00:00:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'})}</p><section class="panel"><span class="note">Expected total</span><h3>${calendarTotals(all)}</h3><span class="note">Still upcoming</span><h3>${calendarTotals(upcoming)}</h3></section><h3>Upcoming <small>· ${upcoming.length}</small></h3><div class="rows subscription-rows month-charge-list">${upcoming.map(spendRecordRow).join('')||'<p class="note">No more renewals scheduled this month.</p>'}</div><h3>Earlier this month <small>· ${earlier.length}</small></h3><div class="rows subscription-rows month-charge-list">${earlier.map(spendRecordRow).join('')||'<p class="note">No earlier charges scheduled.</p>'}</div><p class="note">Scheduled charges are estimates, not confirmed payments. Subscriptions without a renewal date are excluded.</p>`;}
document.addEventListener('click',e=>{const platform=e.target.closest('[data-spend-platform]'),record=e.target.closest('[data-spend-record]');if(platform){platformOrigin={name:platform.dataset.spendPlatform,spendingReturn:platform.dataset.spendOrigin};go('Platform subscriptions');}else if(record){const r=allTrackedRecords().find(r=>r.id===record.dataset.spendRecord);if(r){state.manual={...r};demoName=r.name;demoPrice=r.price;go('Detail');}}});

function homeStats(){const records=spendingRecords(),due=homeMonthEvents().filter(r=>r.renewal>=calendarToday&&r.renewal<=new Date(Date.parse(calendarToday+'T00:00:00Z')+7*86400000).toISOString().slice(0,10));return `<div class="stats">${[['Tracking',records.filter(r=>!r.trialEnded).length],['Upcoming · 7 days',due.length]].map(([label,value])=>panel(`<span class="metric-label">${label}</span><strong>${value}</strong>`)).join('')}</div>`;}
function homeForecast(){const [year,month]=calendarToday.split('-').map(Number),months=Array.from({length:6},(_,i)=>{const date=new Date(Date.UTC(year,month-1+i,1));return {label:date.toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'}),events:calendarEvents({year:date.getUTCFullYear(),month:date.getUTCMonth()})};}),currencies=[...new Set(months.flatMap(m=>m.events.map(r=>r.currency)))];return `<section class="panel chart-card"><h3>Coming up · 6 months</h3><p class="note">Expected full-month charges</p>${currencies.map(currency=>{const data=months.map(m=>({label:m.label,value:m.events.filter(r=>r.currency===currency&&r.expectedCharge!==false).reduce((n,r)=>n+Number(r.price),0)})),max=Math.max(...data.map(r=>r.value),1);return `<p class="note">${currency}</p><div class="bar-chart">${data.map((r,i)=>`<button class="bar-column ${i===0?'selected':''}" data-currency="${currency}" data-month="${r.label}" data-value="${r.value.toFixed(2)}" aria-label="${r.label}: ${currency} ${r.value.toFixed(2)} expected"><span class="bar-value">${r.value.toFixed(2)}</span><span class="bar-space"><i style="height:${r.value/max*100}%"></i></span><small>${r.label}</small></button>`).join('')}</div><p class="chart-selection">${data[0].label} · ${currency} ${data[0].value.toFixed(2)} expected</p>`;}).join('')}</section>`;}

function homeSkeleton(){
 const line=(width='100%',height=12)=>`<span class="sk-block" style="width:${width};height:${height}px"></span>`;
 const row=()=>`<div class="sk-row">${line('36px',36)}<div class="sk-grow">${line('62%',12)}${line('88%',7)}</div>${line('54px',12)}</div>`;
 return `<div class="home-dashboard home-loading"><div class="head"><h2>Home</h2>${btn('+','Add sheet','plus')}</div><p class="sk-announcement" role="status">Loading your dashboard</p><div class="home-skeleton" aria-busy="true" aria-label="Dashboard loading"><div aria-hidden="true"><section class="panel sk-renewal">${line('35%',9)}${row()}</section><div class="stats">${[1,2].map(()=>`<section class="panel">${line('64%',10)}${line('28%',25)}</section>`).join('')}</div><section class="panel sk-month">${line('37%',14)}${line('58%',10)}${line('64%',28)}${line('100%',5)}${line('43%',9)}<div class="sk-divider"></div>${line('77%',10)}</section><section class="panel sk-platforms">${line('43%',15)}${line('66%',10)}${[1,2,3,4].map(row).join('')}</section><section class="panel">${line('58%',14)}${line('72%',10)}<div class="sk-bars">${[55,75,60,90,66,78].map(h=>line('12%',h)).join('')}</div></section>${line('58%',14)}<section class="panel">${row()}${row()}</section></div></div></div>`;
}

function listEmptyState(noRecords=false){return `<div class="list-no-results"><div class="list-empty-mascot"><img src="assets/loop-sad.svg?v=2" alt="" aria-hidden="true"></div><h3>${noRecords?'No subscriptions yet':'No subscriptions found'}</h3><p>${noRecords?'Add your first subscription to keep track of your renewals.':'Try another service name or choose a different filter.'}</p><div class="list-empty-actions"><button data-go="Add form" aria-label="Add subscription manually"><span class="list-add-plus" aria-hidden="true">+</span><span>Add manually</span></button></div></div>`;}

// Native select behavior with one shared, inset icon treatment.


function listStatusOptions(){return [['Active','active'],['On trial','trial'],['Trial ended','trial-ended'],['Renewing soon','renewing-soon'],['Due today','due-today'],['Needs date','needs-date'],['Cancelled','cancelled'],['Expired','expired']];}
function seedListFilters(route){const key=({'List · no renewal':'needs-date','List · upcoming':'renewing-soon','List · active':'active','List · trial':'trial','List · trial ended':'trial-ended','List · due today':'due-today','List · cancelled':'cancelled','List · expired':'expired'})[route];if(key)listView.filters=new Set([key]);}
function matchesListFilters(item,filters,query){return (!filters.size||filters.has(subscriptionStatus(item).key))&&item.name.toLowerCase().includes(query.trim().toLowerCase());}
function selectedListChips(){return listStatusOptions().filter(([,key])=>listView.filters.has(key)).map(([label,key])=>`<button class="selected-status status-${key}" data-remove-status="${key}" aria-label="Remove ${label} filter"><span>${label}</span><span class="filter-chip-cross" aria-hidden="true">×</span></button>`).join('')+(listView.filters.size?'<button class="filter-clear-all" data-clear-list-filters>Clear all</button>':'');}
function listFilterControls(){return `<div class="list-filter-controls"><div class="list-filter-toolbar"><button class="list-filter-trigger" data-open-list-filter aria-haspopup="dialog" aria-expanded="false" aria-label="Status filters${listView.filters.size?', '+listView.filters.size+' selected':''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M7 12h10M10 18h4"/></svg><span>Status filters</span><span class="filter-badge" ${listView.filters.size?'':'hidden'}>${listView.filters.size}</span></button></div></div>`;}
function refreshListFilters(){document.querySelectorAll('.selected-statuses').forEach(el=>{el.innerHTML=selectedListChips();el.hidden=!listView.filters.size;});document.querySelectorAll('[data-open-list-filter]').forEach(el=>{el.setAttribute('aria-label','Status filters'+(listView.filters.size?', '+listView.filters.size+' selected':''));const badge=el.querySelector('.filter-badge');badge.textContent=listView.filters.size;badge.hidden=!listView.filters.size;});document.querySelectorAll('[data-clear-list-filters]').forEach(el=>el.hidden=!listView.filters.size);document.querySelectorAll('.list-all-statuses').forEach(el=>el.hidden=!!listView.filters.size);document.querySelectorAll('[data-list-status]').forEach(el=>el.checked=listView.filters.has(el.dataset.listStatus));const total=subscriptionListData().filter(item=>matchesListFilters(item,listView.filters,listView.query)).length;document.querySelectorAll('.filter-result-summary').forEach(el=>el.textContent=total+' matching subscription'+(total===1?'':'s'));refreshListResults();}
function updateListFilters(){if(current.startsWith('List')){current='List';history.replaceState(null,'','#list');document.querySelector('#title').textContent='List';renderNav();}refreshListFilters();}
function closeListFilter(phone){const overlay=phone.querySelector('.list-filter-overlay');if(!overlay)return;overlay.remove();phone.querySelectorAll('[data-list-filter-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-list-filter-inert');});const trigger=phone.querySelector('[data-open-list-filter]');trigger?.setAttribute('aria-expanded','false');trigger?.removeAttribute('aria-controls');trigger?.focus();}
function openListFilter(trigger){document.querySelectorAll('.list-filter-overlay').forEach(el=>closeListFilter(el.closest('.phone')));const phone=trigger.closest('.phone'),data=subscriptionListData(),overlay=document.createElement('div');overlay.className='list-filter-overlay';overlay.innerHTML=`<div class="list-filter-shade" data-close-list-filter></div><section class="status-filter-dialog" role="dialog" aria-modal="true" aria-label="Filter subscriptions by status" id="${phone.id}-status-filter-dialog" style="max-height:${phone.clientHeight-64}px"><header><div><h3>Filter by status</h3><p>Choose one or more</p></div><button data-close-list-filter aria-label="Close filters">×</button></header><div class="status-filter-options">${listStatusOptions().map(([label,key])=>`<label class="status-filter-option"><input type="checkbox" data-list-status="${key}" ${listView.filters.has(key)?'checked':''}><span class="status-${key}">${label}</span><small>${data.filter(r=>subscriptionStatus(r).key===key).length}</small></label>`).join('')}</div><footer><span class="filter-result-summary" role="status"></span><button class="filter-clear-all" data-clear-list-filters ${listView.filters.size?'':'hidden'}>Clear all</button><button class="filter-done" data-close-list-filter>Done</button></footer></section>`;for(const el of phone.children){if(!el.inert){el.inert=true;el.dataset.listFilterInert='true';}}phone.append(overlay);trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls',phone.id+'-status-filter-dialog');refreshListFilters();overlay.querySelector('[aria-label="Close filters"]').focus();}
document.addEventListener('click',e=>{const open=e.target.closest('[data-open-list-filter]'),close=e.target.closest('[data-close-list-filter]'),remove=e.target.closest('[data-remove-status]'),clear=e.target.closest('[data-clear-list-filters]');if(open)openListFilter(open);else if(close)closeListFilter(close.closest('.phone'));else if(remove){const phone=remove.closest('.phone');listView.filters.delete(remove.dataset.removeStatus);updateListFilters();phone.querySelector('[data-open-list-filter]')?.focus();}else if(clear){const phone=clear.closest('.phone');listView.filters.clear();updateListFilters();(phone.querySelector('.list-filter-overlay input')||phone.querySelector('[data-open-list-filter]'))?.focus();}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-list-status]'))return;const key=e.target.dataset.listStatus;if(e.target.checked)listView.filters.add(key);else listView.filters.delete(key);updateListFilters();});
document.addEventListener('keydown',e=>{const overlay=document.querySelector('.list-filter-overlay');if(!overlay)return;if(e.key==='Escape'){e.preventDefault();closeListFilter(overlay.closest('.phone'));}else if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button:not([hidden]),input')],first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
